"""Deterministic observations generated by the existing physical simulator.

Truth is used only here to generate benchmarks; it is never an identification
input. Each segment calls the ordinary tank simulation, including its noise.
"""
from .models import resolve
from .models.tanks import integrate


def observations(*, seed=19, noise=.002, validation=False, equilibrium=False, mismatch=False, parameters=None):
    physical=dict(pumpRate=.036,connection=.047,outlet=.026)
    physical.update(parameters or {})
    commands=[(70,1.),(125,.72),(90,.95),(140,.8)] if not validation else [(130,.9),(65,.8),(115,1.),(85,.75)]
    if equilibrium:
        physical=dict(pumpRate=.03,connection=.04,outlet=.03)
        commands=[(100,1.)]*4
    initial=[1.5625,1.] if equilibrium else ([1.1,.75] if not validation else [.8,1.2])
    rows=[]
    for segment,(pump,valve) in enumerate(commands):
        config=resolve('coupled-tanks').validate(dict(**physical,initial1=initial[0],initial2=initial[1],
            pumpControl=pump,valve=valve,duration=50,step=1,integrationStep=.025,seed=seed+segment,noise=noise,
            fault='tank_leak' if mismatch else 'healthy',start=0,severity=.5,leakCoefficient=.025))
        measured,states=integrate(config)
        if rows: rows.pop()  # Retain the new command at a segment boundary.
        rows.extend(dict(r,t=r['t']+segment*50) for r in measured)
        initial=[states[-1]['level1'],states[-1]['level2']]
    return rows,physical


def csv_observations(rows):
    keys=('t','level1','level2','inlet','transfer','outlet','pump','valve')
    return ','.join(keys)+'\n'+'\n'.join(','.join(str(r[k]) for k in keys) for r in rows)
